<?php
namespace App\Http\Controllers;
use App\Models\Student;
use App\Http\Requests\StoreStudentRequest;
class StudentController extends Controller { public function index(){ $students=auth()->user()->isAluno()?Student::where('id',auth()->user()->student_id)->paginate(10):Student::withCount('enrollments')->orderBy('name')->paginate(10); return view('students.index',compact('students')); } public function create(){ $this->authorize('create',Student::class); return view('students.create'); } public function store(StoreStudentRequest $request){ $this->authorize('create',Student::class); Student::create($request->validated()); return redirect()->route('students.index')->with('success','Aluno cadastrado com sucesso.'); } public function show(Student $student){ $this->authorize('view',$student); $student->load('enrollments.course'); return view('students.show',compact('student')); } public function edit(Student $student){ $this->authorize('update',$student); return view('students.edit',compact('student')); } public function update(StoreStudentRequest $request,Student $student){ $this->authorize('update',$student); $student->update($request->validated()); return redirect()->route('students.show',$student)->with('success','Dados atualizados com sucesso.'); } public function destroy(Student $student){ $this->authorize('delete',$student); $student->delete(); return redirect()->route('students.index')->with('success','Aluno removido com sucesso.'); } }
